if(typeof require==='function'){var Classy=require('./classy');}var ProjectileState=Classy.newClass().name('ProjectileState');ProjectileState.fields({data:{}});ProjectileState.constructor('withState',function(id,playerId,type,x,y,speedX,speedY){this.data.id=id;this.data.playerId=playerId;this.data.type=type;this.data.x=x;this.data.y=y;this.data.speedX=speedX;this.data.speedY=speedY;});ProjectileState.constructor('withObject',function(obj){this.data=obj;});ProjectileState.methods({getId:function(){return this.data.id;},getPlayerId:function(){return this.data.playerId;},getType:function(){return this.data.type;},getX:function(){return this.data.x;},getY:function(){return this.data.y;},getSpeedX:function(){return this.data.speedX;},getSpeedY:function(){return this.data.speedY;},toObj:function(){return this.data}});if(typeof module==='object'){module.exports=ProjectileState;}